        address clone;
        assembly {
            clone := create(0, add(code, 0x20), mload(code))
        }
        require(clone != address(0), "clone failed");
        c = C(clone);
    }
    function testFuzz_property(address fuzzedOwner) public {
        // The property holds for any owner address used during deployment,
        // but the fuzzer cannot change the already-deployed clone's owner.
        // Instead, we assert that c.owner() equals the known immutable owner.
