pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address expectedCollateral, address expectedDebt) public {
        // Assemble the expected immutable data layout: owner (20 bytes) + collateral (20 bytes) + debt (20 bytes) + factory (20 bytes)
        // The getters read from calldata after the deployment code; we can directly read the immutable slots.
        // Use vm.assume to ensure addresses are distinct so the bug is detectable.
        vm.assume(expectedCollateral != expectedDebt);
        // The property: collateral() must return the address at immutable offset 0x14 (collateral token),
        // which is the second address in the immutable args (bytes 20..39 after the first 20-byte owner).
        // We deploy a fresh C with the given immutables using the factory pattern, but since C is Clone,
        // we can instead check directly: the getter _getArgAddress(0x14) reads the collateral address,
        // and _getArgAddress(0x28) reads the debt address. The bug swaps them.
        // So collateral() must equal _getArgAddress(0x14) and NOT _getArgAddress(0x28).
        // However, _getArgAddress is internal, so we cannot call it directly.
        // We will deploy a minimal wrapper to expose the immutables, but that's not allowed.
        // Instead, we reason: the correct C returns the collateral token address which is the same as
        // calling debt() on a different buggy instance where debt() reads offset 0x28.
        // But we can construct a test by deploying two clones via the factory with known immutables
        // and comparing collateral() vs debt() values. However, we cannot use the factory here.
        // The simplest universal property: for any C, the address returned by collateral() and the address
        // returned by debt() should be DIFFERENT when the two tokens are distinct in the immutable args.
        // To check this without internal getters, we need to create a C clone with known immutables.
        // Since C is Clone and inherits ClonesWithImmutableArgs, we can use the library to deploy a clone
        // with arbitrary immutable data. Then we can check the return values.
        // We'll deploy a helper contract that uses the library to create the clone.
        // Actually, we can just deploy a new C via the factory or directly clone. Let's create a clone directly.

        // Deploy a minimal factory-like helper that can clone C with given immutables.
        Helper helper = new Helper();
        address ownerAddr = address(this);
        C clone = C(helper.deployClone(address(c), ownerAddr, expectedCollateral, expectedDebt, address(this)));

        // Now check the property: collateral() should return expectedCollateral, NOT expectedDebt.
        // The buggy version returns expectedDebt.
        assertTrue(clone.collateral() == expectedCollateral);
    }
}

contract Helper {
    using ClonesWithImmutableArgs for address;
    function deployClone(
        address implementation,
        address owner_,
        address collateral_,
        address debt_,
        address factory_
    ) external returns (address clone) {
        bytes memory data = abi.encodePacked(owner_, collateral_, debt_, factory_);
        clone = implementation.clone(data);
    }
}

